## Full‑featured example (copy‑paste ready)

```js
// Assuming you already have a MapLibre GL JS map instance called `map`
map.on('click', e => {
  // 1️⃣ Safely pull out the nested payload
  const rawInfo = e?.features?.[0]?.properties?.info;

  // 2️⃣ If nothing there, exit early (or handle however you like)
  if (!rawInfo) {
    console.warn('Clicked feature has no “info” property');
    return;
  }

  // 3️⃣ If the payload is a JSON string, turn it into an object
  let info;
  if (typeof rawInfo === 'string') {
    try {
      info = JSON.parse(rawInfo);
    } catch (err) {
      console.error('Invalid JSON in info property', err);
      return; // abort –‑ we can’t safely read fields
    }
  } else {
    info = rawInfo; // already an object
  }

  // 4️⃣ Read the fields you care about, with defaults
  const name   = info?.name   ?? 'Unnamed';
  const age    = info?.age    ?? 0;
  const status = info?.status?.toUpperCase?.() ?? 'N/A';
  const city   = info?.address?.city ?? 'Unknown city';
  const firstTag = info?.tags?.[0] ?? 'no‑tags';

  // 5️⃣ Do something with the data (e.g., show a popup)
  new maplibregl.Popup()
    .setLngLat(e.lngLat)
    .setHTML(`
      <strong>${name}</strong><br>
      Age: ${age}<br>
      Status: ${status}<br>
      City: ${city}<br>
      First tag: ${firstTag}
    `)
    .addTo(map);
});
```

