## Full example – reading a nested property and using it

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Read nested property from queryRenderedFeatures</title>
  <script src="https://api.mapbox.com/mapbox-gl-js/v2.15.0/mapbox-gl.js"></script>
  <link href="https://api.mapbox.com/mapbox-gl-js/v2.15.0/mapbox-gl.css" rel="stylesheet" />
  <style>#map { position:absolute; top:0; bottom:0; width:100%; }</style>
</head>
<body>
<div id="map"></div>
<script>
mapboxgl.accessToken = 'YOUR_TOKEN';
const map = new mapboxgl.Map({
  container: 'map',
  style: 'mapbox://styles/mapbox/streets-v12',
  center: [-122.447303, 37.753574],
  zoom: 12
});

map.on('load', () => {
  // Add a source that contains a nested property
  map.addSource('places', {
    type: 'geojson',
    data: {
      type: 'FeatureCollection',
      features: [{
        type: 'Feature',
        geometry: { type: 'Point', coordinates: [-122.447303, 37.753574] },
        properties: {
          name: 'Mission District',
          // <-- nested object
          stats: {
            population: 60000,
            medianIncome: 85000
          }
        }
      }]
    }
  });

  map.addLayer({
    id: 'places',
    type: 'circle',
    source: 'places',
    paint: { 'circle-radius': 8, 'circle-color': '#ff6600' }
  });

  // Click handler that reads the nested property
  map.on('click', (e) => {
    const feats = map.queryRenderedFeatures(e.point, { layers: ['places'] });
    if (!feats.length) return;

    const f = feats[0];
    const stats = f.properties.stats; // <-- object
    console.log('Full stats object:', stats);

    // Grab a sub‑field safely
    const pop = f.properties.stats?.population;
    const income = f.properties.stats?.medianIncome;

    new mapboxgl.Popup()
      .setLngLat(e.lngLat)
      .setHTML(`
        <strong>${f.properties.name}</strong><br/>
        Population: ${pop?.toLocaleString() ?? 'n/a'}<br/>
        Median income: $${income?.toLocaleString() ?? 'n/a'}
      `)
      .addTo(map);
  });
});
</script>
</body>
</html>
```

*What you see in the console*  

```
Full stats object: {population: 60000, medianIncome: 85000}
```

*What the popup shows*  

```
Mission District
Population: 60,000
Median income: $85,000
```

