## 3. Adding many icons on the fly (e.g. per‑feature)

If you have a dataset where each feature may need a *different* icon that you only discover at runtime (e.g. icons stored in a database, user‑uploaded SVGs, etc.), you can:

1. **Pre‑process the list of needed icons** (e.g. collect unique URLs or IDs).
2. **Load each one asynchronously** and add it to the map.
3. **Reference the icon name from a feature property** using a data‑driven `icon-image`.

### 3.1. Data‑driven `icon-image`

```js
// Assume each feature has a property `iconId` that matches the name we will register.
map.addLayer({
  id: 'dynamic-icons',
  type: 'symbol',
  source: 'my-geojson',
  layout: {
    // The property value is looked up in the image registry.
    'icon-image': ['get', 'iconId'],
    'icon-size': 0.8,
    'icon-allow-overlap': true
  }
});
```

### 3.2. Bulk‑load helper

```js
/**
 * Load a set of icons and register them.
 * @param {MapLibreMap} map
 * @param {Object.<string,string>} nameToUrl  map of image name → URL
 * @returns {Promise<void>}
 */
async function addIcons(map, nameToUrl) {
  const promises = Object.entries(nameToUrl).map(async ([name, url]) => {
    // Skip if we already have it (useful when re‑running after a style change)
    if (map.hasImage(name)) return;

    // `loadImage` returns a Promise in newer MapLibre versions (v4+)
    const image = await new Promise((resolve, reject) => {
      map.loadImage(url, (err, img) => err ? reject(err) : resolve(img));
    });

    // Optional: set `sdf: true` if you want to tint the icon with `icon-color`
    map.addImage(name, image, { sdf: false });
  });

  await Promise.all(promises);
}
```

**Usage**

```js
map.on('load', async () => {
  // 1️⃣ Add the source (GeoJSON with an `iconId` property)
  map.addSource('my-geojson', { type: 'geojson', data: myGeojson });

  // 2️⃣ Determine which icons we need
  const neededIcons = {};
  myGeojson.features.forEach(f => {
    const id = f.properties.iconId;          // e.g. "restaurant", "park", …
    if (!neededIcons[id]) {
      neededIcons[id] = `https://my.cdn.com/icons/${id}.png`;
    }
  });

  // 3️⃣ Load & register them
  await addIcons(map, neededIcons);

  // 4️⃣ Add the layer that uses the data‑driven icon name
  map.addLayer({
    id: 'my-geojson-layer',
    type: 'symbol',
    source: 'my-geojson',
    layout: {
      'icon-image': ['get', 'iconId'],
      'icon-size': 0.7,
      'icon-allow-overlap': true
    }
  });
});
```

**Result:** Each feature shows the icon that matches its `iconId`. If a new feature appears later with a brand‑new `iconId`, just call `addIcons` again for that one name and the layer will instantly pick it up (no need to recreate the layer).

---

## 4. Handling “missing‑icon” errors automatically

Sometimes you have a layer that already exists and a feature suddenly references an icon that isn’t in the registry yet. Instead of manually tracking every possible name, you can **listen for the error event** and load the missing image on demand.

```js
// Global map error handler
map.on('error', e => {
  // MapLibre prefixes its own errors with "Error: ..."
  const msg = e?.error?.message ?? '';
  const missingMatch = msg.match(/Image "([^"]+)" does not exist in the style sprite/);
  if (!missingMatch) return; // not an icon‑missing error

  const missingName = missingMatch[1];
  console.warn(`Icon "${missingName}" missing – trying to load it on‑the‑fly`);

  // Build the URL from your own naming convention
  const url = `https://my.cdn.com/icons/${missingName}.png`;

  map.loadImage(url, (err, img) => {
    if (err) {
      console.error(`Failed to load dynamic icon ${missingName}`, err);
      return;
    }
    map.addImage(missingName, img);
    // Force a re‑render so the newly added image is used immediately
    map.triggerRepaint();
  });
});
```

**Why this works**

* The error is emitted *after* the style has been parsed but *before* the frame is drawn, giving you a tiny window to inject the missing image.
* `map.triggerRepaint()` forces MapLibre to re‑evaluate the style with the newly added image, so the offending feature appears without a full `setStyle` reload.

---

## 5. Adding icons from **Canvas** or **SVG** (no external URL)

If you generate icons on the client (e.g. draw a badge on a `<canvas>` or convert an SVG string to a bitmap), you can still use `addImage`.

### 5.1. From a Canvas

```js
function canvasIcon(text, bgColor = '#ff6600') {
  const size = 64;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');

  // Background circle
  ctx.fillStyle = bgColor;
  ctx.beginPath();
  ctx.arc(size / 2, size / 2, size / 2, 0, Math.PI * 2);
  ctx.fill();

  // Text
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 32px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, size / 2, size / 2);

  return canvas;
}

// Usage
const myCanvas = canvasIcon('A', '#2a9d8f');
map.addImage('canvas‑icon‑A', myCanvas);
```

### 5.2. From an SVG string

```js
function svgToImage(svgString, callback) {
  const svgBlob = new Blob([svgString], { type: 'image/svg+xml' });
  const url = URL.createObjectURL(svgBlob);
  const img = new Image();
  img.onload = () => {
    // Optionally draw onto a canvas to get an ImageBitmap (better for WebGL)
    const canvas = document.createElement('canvas');
    canvas.width = img.width;
    canvas.height = img.height;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0);
    canvas.toBlob(blob => {
      createImageBitmap(blob).then(bmp => callback(null, bmp));
    });
  };
  img.onerror = e => callback(e);
  img.src = url;
}

// Example
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64">
               <circle cx="32" cy="32" r="30" fill="#e76f51"/>
               <text x="32" y="38" font-size="32"

