## 3. Full‑featured example (combining everything)

```js
// ---------------------------------------------------
// 1️⃣  Initialise the map
// ---------------------------------------------------
const map = new maplibregl.Map({
  container: 'map',
  style: 'https://example.com/your-style.json',
  center: [-122.45, 37.78],
  zoom: 12,
});

// ---------------------------------------------------
// 2️⃣  Listen for missing‑image events
// ---------------------------------------------------
map.on('styleimagemissing', async (e) => {
  // 2a – Try a remote PNG first
  const remoteUrl = `/icons/${e.id}.png`;
  try {
    const img = await loadImage(remoteUrl);
    map.addImage(e.id, img, { sdf: false });
    return;
  } catch (_) {
    // continue – maybe we have a canvas‑based fallback
  }

  // 2b – If the id follows a known pattern, draw a canvas icon
  if (/^dot-\d+$/.test(e.id)) {
    const canvas = drawDotIcon(e.id);
    map.addImage(e.id, canvas, { sdf: false });
    return;
  }

  // 2c – Final fallback: a generic “question‑mark” placeholder
  const placeholder = document.getElementById('placeholder-img'); // <img id="placeholder-img" src="missing.svg">
  map.addImage(e.id, placeholder);
});

// ---------------------------------------------------
// 3️⃣  Helper: draw a coloured dot on a canvas
// ---------------------------------------------------
function drawDotIcon(id) {
  const hue = Number(id.split('-')[1]) % 360;
  const size = 64;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = `hsl(${hue}, 80%, 50%)`;
  ctx.beginPath();
  ctx.arc(size / 2, size / 2, size / 2 - 4, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 4;
  ctx.stroke();

  return canvas;
}
```

**Result:**  
Whenever the style asks for `"icon-image": "dot-120"` (or any other name you haven’t pre‑packed), the `styleimagemissing` handler runs, creates the appropriate image, registers it, and the layer instantly renders without a flicker.

