          // <-- this name does NOT exist yet
          'icon-image': 'my‑missing‑icon',
          // optional: size, offset, etc.
          'icon-size': 1.2
        }
      }]
    },
    center: [-122.447303, 37.753574],
    zoom: 12
  });

  // -----------------------------------------------------------------
  // 2️⃣  Listen for the “styleimagemissing” event
  // -----------------------------------------------------------------
  map.on('styleimagemissing', async (e) => {
    console.warn(`🛑  Style asked for missing image "${e.id}" (type=${e.type})`);

    // ---------------------------------------------------------------
    // 2a️⃣  Decide what to do – try to fetch a real image first
    // ---------------------------------------------------------------
    const fallbackUrl = 'https://raw.githubusercontent.com/maplibre/maplibre-gl-js/main/docs/assets/marker.png';
    const imageUrl = `https://my.cdn.com/icons/${e.id}.png`; // <-- where you *expect* the icon to live

    // Helper that loads an image and returns an HTMLImageElement (or null on error)
    const loadImage = (url) => new Promise(resolve => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => resolve(img);
      img.onerror = () => resolve(null);
      img.src = url;
    });

    // Try the “real” URL first, then the generic fallback
    let img = await loadImage(imageUrl);
    if (!img) {
      console.info(`🔎  Could not load "${imageUrl}", falling back to generic marker`);
      img = await loadImage(fallbackUrl);
    }

    // ---------------------------------------------------------------
    // 2b️⃣  If we finally have an image, add it to the style registry
    // ---------------------------------------------------------------
    if (img) {
      // `addImage` will replace the placeholder that triggered the event
      // The third argument (`options`) is optional – set `sdf:true` for SDF icons.
      map.addImage(e.id, img);
      console.log(`✅  Added image "${e.id}" (size ${img.width}×${img.height})`);
    } else {
      // -----------------------------------------------------------
      // 2c️⃣  No image at all → add a tiny “missing‑icon” placeholder
      // -----------------------------------------------------------
      const placeholder = document.createElement('canvas');
      placeholder.width = placeholder.height = 32;
      const ctx = placeholder.getContext('2d');
      ctx.fillStyle = '#ff5555';
      ctx.fillRect(0, 0, 32, 32);
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(8, 8);
      ctx.lineTo(24, 24);
      ctx.moveTo(24, 8);
      ctx.lineTo(8, 24);
      ctx.stroke();

      map.addImage(e.id, placeholder);
      console.warn(`⚠️  Added placeholder for "${e.id}"`);
    }

    // ---------------------------------------------------------------
    // 3️⃣  Force a re‑paint of the layer that was waiting on the image.
    // ---------------------------------------------------------------
    // The map automatically re‑renders once the image is added,
    // but if you have a custom source that loads later you may want:
    // map.triggerRepaint();
  });

  // -----------------------------------------------------------------
  // 4️⃣  (Optional) Global error listener – useful for debugging
  // -----------------------------------------------------------------
  map.on('error', (e) => {
    // e.error contains the original Error object
    console.error('MapLibre error event:', e.error);
  });
</script>
</body>
</html>
```

### What the code does

| Step | What happens | Why it matters |
|------|--------------|----------------|
| **1️⃣** | Create a map with a style that references `my‑missing‑icon`. No image is pre‑loaded. | Guarantees the `styleimagemissing` event will fire. |
| **2️⃣** | Register `map.on('styleimagemissing', …)`. The callback receives `{id, type}`. | This is the **only** built‑in hook for “icon not present”. |
| **2a️⃣** | Try to fetch the image from a predictable URL (`my.cdn.com/icons/<id>.png`). If that fails, fall back to a generic marker. | Gives you a chance to load the *real* asset on‑demand. |
| **2b️⃣** | If an image is obtained, call `map.addImage(id, img)`. | Registers the image under the exact name the style asked for, unblocking the layer. |
| **2c️⃣** | If nothing could be loaded, create a tiny red‑cross canvas and add that as a placeholder. | Guarantees the map never shows a blank or broken symbol. |
| **3️⃣** | (Optional) `map.triggerRepaint()` – useful when you add the image after the source data has already been parsed. | Guarantees the layer is redrawn immediately. |
| **4️⃣** | Global `error` listener – catches any other style‑related errors (e.g., malformed JSON). | Helpful for debugging in production. |

---

## 3. Common variations & gotchas

| Situation | Recommended tweak |
|-----------|-------------------|
| **Multiple missing icons at once** | The event fires **once per missing id**. Keep a `Set` of ids you’re already loading to avoid duplicate network requests. |
| **SDF (signed‑distance‑field) icons** | When you add the image, pass `{sdf: true}` in the options. Example: `map.addImage(e.id, img, {sdf: true});` |
| **Icons that are sprites in a sprite sheet** | If you have a sprite JSON/PNG pair, you can call `map.addSprite('my-sprite', spriteJSON, spritePNG)`. The `styleimagemissing` event will still fire for each missing name, but you can pre‑load the whole sprite once and then call `map.addSprite`. |
| **Icons that depend on the map’s pixel ratio** | Load a `@2x` version when `window.devicePixelRatio > 1`. Example: `const suffix = window.devicePixelRatio > 1 ? '@2x' : ''; const url = `${base}/${e.id}${suffix}.png`;` |
| **You want to *ignore* the missing icon** | Add a tiny transparent 1×1 canvas: `const empty = document.createElement('canvas'); empty.width = empty.height = 1; map.addImage(e.id, empty);` This prevents the layer from being hidden while keeping the visual unchanged. |
| **You need to know *why* the image is missing** | The `styleimagemissing` event does **not** give you the source of the request (layer name, source, etc.). If you need that context, keep a map of `layerId → expectedIconId` yourself, then cross‑reference inside the handler. |
| **You want to log the problem to a remote monitoring service** | Inside the handler, `fetch('/log-missing-icon', {method:'POST', body:JSON.stringify({id:e.id, url:imageUrl})});` – just be sure to debounce to avoid spamming. |

